// STAND_INS: label -> what and why.
export const STAND_INS = {
  "H-UIIN": "act_tsk(84): UI_IN (entry 0x5014b736) is started by the harness; then one push of every group's idle image (S-KEYBITS)",
  "H-UIINRING": "the ring init 0x5014cb5f (ring pointers 0xa32dab9c/0xa32daba0 = 0xa32dab54) before H-UIIN, the one call of UI_IN's module init 0x5014bf91 (at 0x5014bf9e) the ring needs; the rest of that init does not run (its other stores write the BSS value 0; 0x5014e3ab, 0x5014ce00, 0x5005d36a, 0x5014d62e, 0x5014d97a are not traced; 0x5014d49e sets group 4's image 0x629887e4 and old state to the polarity bits, D, and does not run: both stay 0)",
  "S-KEYBITS": "the producers of UI_IN's raw key bits (SCPU RX, the poller) are not traced: the harness pushes a whole group image of groups 0..3 (1..3 on a body with H-SCPUPORT) with the firmware's push 0x5014cb74 and sets UI_IN's flag (set_flg); group 4 goes through the firmware's own producer (H-G4SET) after the idle push. Idle image: a type-2 key released (bit != polarity), a switch bit 0 (the old state of every lab before M10), the monitor bit 1 (\"not closed\", C2) and the mode dial one-hot at index 0 (the index-to-mode map is ?); on a ported body the power lever on and the USB connection 0x0400 with no cable, by their states (play.mjs IDLE_SWITCH_STATES), but in the group the firmware's group-4 producer pushes: the E143 family keeps 0x0400 at state 0",
  "H-SCPUIRQ": "(a body with the SCPU's port path) what the SCPU init, which does not run, does for its event word: the ports at the idle levels, their events cleared as the init clears them (127 to the event word 0x98), and IRQ 320 attached at level 5 to the init's handler through the firmware's attach; the handler then runs natively (docs/hle-gaps.md 4.7.2)",
  "H-UIINPORT": "(a body with the SCPU's port path) UI_IN's IRQ 320 callback registered through the firmware's registration, as UI_IN's port init (not run) registers it, and group 0's old state set from the port byte by the firmware's init that UI_IN's start stage (not run) calls first, so the idle levels decode nothing; any later registration of another callback is refused (PER_SCPU registers its own natively at its start, H-SCPUSTART, before UI_IN's)",
  "H-SCPUPORT": "(a body with the SCPU's port path) group 0 (power lever, Fn lever, S1, 0x1229, and the SCPU's three request lines, held high) is the SCPU interface's port levels (bit 31 of the window's port word 0xa0 + 4k), set through the lab's doorbell: each changed port sets its event bit, IRQ 320 is taken natively at the idle point, and its handler and UI_IN's callback push the port byte and set UI_IN's flag (iset_flg) natively. That a level change of either direction sets the event bit is I",
  "H-GIOSLOTS": "the reset of the GIO interrupt slots that the GIO init, which does not run, ends with, natively: with --hdmi on before the display init, which then registers the HDMI hot-plug pin's handler and attaches its group's IRQ 109 natively (docs/hle-gaps.md 4.9); else at the sub-CPU link's start (H-SCPUSTART), so that PER_SCPU's registration of pin 102 takes a slot and attaches IRQ 119 natively",
  "S-HDMISINK": "(--hdmi on) the sink an hdmi plug input puts on the port: a 1080p60 monitor's EDID (base block and a CTA-861 extension) composed for the lab, not captured from a monitor (src/lab/edid.mjs). The hot-plug pin's interrupt, the transmitter's start, the E-DDC reads with IRQ 239, the EDID's checks and parse and the report to UI_IN run natively. The sink has no SCDC (an HDMI 1.4 sink): the HDMI open's SCDC write is not acknowledged",
  "A-HDMI-1": "(--hdmi on) the hot-plug pin's GIO status bit is set when the pin rises; nothing is set when it falls (the firmware has turned the pin's interrupt off by then). At an unplug the transmitter sets 0x92 bits 0..3, both bits of its hot-plug detect pair and of its receiver sense pair: which bit of a pair a falling line sets is not read, and the driver takes each pair whole, so the choice does not change its path (docs/hle-gaps.md 4.9)",
  "H-FILEINIT": "(a body with the file system, src/fw/models.mjs card_fs) the file system's bring-up natively in the boot task's place, before the application starts: its queues and semaphores, logsec's and the SD host's init, the file layer (reading its NAND area through S-FSNAND), the card driver's detect states, and FILEFGND and DCFPROC_SUB started (docs/hle-gaps.md 4.8)",
  "H-FILECLBK": "(a body with the file system) FILECLBK, the file module's task, started with act_tsk after H-FILEINIT (the boot's start of it is not traced); the application's requests to the file module's queue then go to it (S-MODACK leaves them)",
  "S-SDHOST": "(a body with the file system) the SD host's registers: both ports' pages and the GPIO page of the card's pins and power are lab-stub pages that keep what the firmware writes, and SD_INFO2's clock-divider bit reads set, the one bit the host's set-up polls (I: TMIO's SCLKDIVEN). No SD interrupt is raised: the UHS-II PHY's link-up wait runs out (about 120 ms of lab time), as with a card without UHS-II, and the firmware falls back to the SD interface",
  "S-SDCARD": "(a body with the file system) an 8 GiB SDHC card, or a card of the host's size (OM_EMU_CARD_SIZE; above 32 GiB an SDXC card) (src/lab/sdcard.mjs; its registers the SD specification's, its values the lab's choice) at the firmware's SD command layer: each command is answered there with its response, data and status and its completion called at once, as the layer does for a busy port. sd_mount's card init, sdmem's transfers, the format and the FAT / DCF layers above run natively; the card starts blank (or as the host kept it, OM_EMU_CARD) and the firmware formats it itself. Out of the slot (the input card remove) it answers no command, as an empty slot; it goes back in (card insert) with its sectors as they were, in its idle state",
  "S-SDPOWER": "(a body with the file system whose SD driver asks a power manager for the card's supply: the E144 family's E144, E137, E142, E140, E125, E130, X) the request's synchronous send, to a power manager the lab does not run, is answered 0; a request that returns before its send (E143's, E146's, E147's, E139's) never meets it",
  "S-SDSWITCH": "(a body with the file system whose SD driver switches a card line through its sub-CPU: E118, X) the driver's request, which goes out over the sub-CPU's serial link the lab does not model, is answered at its send: its callback is called with status 0 and the send returns 0, where the driver would otherwise poll for the sub-CPU's answer for good (E122 and E120 set a GIO pin instead)",
  "S-FSNAND": "(a body with the file system) the file system's NAND area (512 KiB of flash) behind the NAND access: it reads erased (0xff), a camera that never saved it, and the firmware's writes are kept for the session; the lab's NAND is not modelled",
  "S-ALBM": "(a body with the file system) the album manager's per-drive init, which the DCF numbering mount calls, returns at once: ALBM_MAIN, which it would start, sends its first request to the image engine (0x5048ee61 on E143, a kind 14 fill on the imgpro unit 0x9c600000, whose model S-IMGPRO the IRQ attach of camapp 3's H-IMGPROINIT serves only after the mount: docs/hle-gaps.md 4.3.1), and the movie module it asks does not run",
  "S-RECFILE": "(a body with the file system but E143, E146 and E147, where REC_FILE runs natively: H-RECFILE) the picture's file at a release's END_SHOOTING_PICTURE, the JPEG the capture pipeline would hand REC_FILE (the recording modules do not run): a JPEG the lab encodes (src/lab/jpeg.mjs: S-SCENE's frame at the capture with each 8 x 8 block its mean, black without the live view; no EXIF). Where the rule reads the build's recorder (src/fw/facts.mjs recorder: E143, E146, E147, E144 and E148) it is recorded as REC_FILE's modules record a file, their requests sent to the file module, which runs each natively: the camera's clock read for the time stamp, the fnode of the next DCF number (named by the stamp's month and day: P1010001.JPG while the clock is not set), the cluster reservation, the chain write, the directory entry and the fnode's registration, so the firmware's image count and next number follow the picture in the same session (X). Elsewhere the file module's own file requests (mkdir, fopen 'wb', fwrite, fclose, as the FlashAir configuration writer makes them) write it at the DCF name the numbering mount gave (the DCF module's initial names), and the firmware counts it from the next mount (X)",
  "H-EXIFINIT": "(E143; E146 and E147 at the addresses and offsets src/fw/facts.mjs recFile reads) the EXIF module's init (0x504298bd, the boot's start function's call) natively before the first picture (nothing in the lab reads it earlier): the EXIF parameter template (0x62a6c358) with its versions and the Make and Model from the settings store; its cache flush answered (src/lab/rec.mjs)",
  "H-RECINIT": "(E143; E146 and E147 at the addresses and offsets src/fw/facts.mjs recFile reads) REC's module init (0x50539665) natively before the first picture: its queues bound to its tasks' flags and its memory pools (src/lab/rec.mjs)",
  "H-RECFILE": "(E143; E146 and E147 at the addresses and offsets src/fw/facts.mjs recFile reads, task 27 on all three) REC_FILE (static task 27, 0x5053f1a4) started with act_tsk after H-RECINIT; it records S2's picture natively from REC_IMAGE's packet: the DCF open of the next number, the cluster reservation, the chain write, the directory entry and the registration through the file module, the buffer freed to REC's pool, the shot's DCF checkout (no pending entry: the HLS side's check-in does not run, a REC warning) and the release of the resources REC_MAIN would have taken (refused, REC warnings) (src/lab/rec.mjs)",
  "S-EXIFPRM": "(E143; E146 and E147 at the addresses and offsets src/fw/facts.mjs recFile reads: on both the block is smaller and the time record at +37452) the shot's EXIF parameter block (the packet's pExifParam), which TAKE fills on the camera and the lab does not run: the template copied by TAKE's own copy (0x504298f9), the camera's clock read natively into the capture's time record (+37800), the dates formatted natively as the EXIF set does (0x5012bd20; 0000:00:00 00:00:00 while the clock is not set), and the crop areas and the digital zoom ratio as the full frame and 1/1 (I), which the header maker divides by; exposure, aperture, ISO, focal length, the lens and the image size stay the template's 0 (the EXIF set 0x5042992d divides by zero in TAKE's state) (src/lab/rec.mjs)",
  "S-RECIMAGE": "(E143; E146 and E147 at the addresses and offsets src/fw/facts.mjs recFile reads: their packet is 276 bytes and REC_IMAGE's image record of 52 bytes, which REC_IMAGE's own init clears and points the packet at, keeps the image's address and size) REC_IMAGE's part (its task does not run: its image needs the image pipeline): the packet REC_IMAGE hands REC_FILE for a single-slot JPEG (Mode 4097, Media 0, no Media2, RecordDevice 1, FileType 1, HandleTarget 1), REC_IMAGE's rec_jpeg_exec run natively on it (the file's buffer from REC's pool 3, the header by rec_jpeg_make_header: SOI, APP1 Exif with the Olympus maker notes and IFD1's thumbnail slot, APP1 XMP, 41984 bytes) and REC_IMAGE's post to REC_FILE's queue natively; lab time runs until REC_FILE has handled it (src/lab/rec.mjs)",
  "S-JPEGENC": "(E143; E146 and E147 at the addresses and offsets src/fw/facts.mjs recFile reads, where Size is the image record's) the image pipeline's work inside rec_jpeg_exec: the JPEG encode (rec_jpeg_make_image 0x50549b42) writes the lab's JPEG (src/lab/jpeg.mjs: S-SCENE's frame at the capture, each 8 x 8 block its mean) without its JFIF APP0 after the 41984-byte header and sets the packet's Size to their sum (I); the image engine's fill of the header area (0x5048ee61, a kind 14 request to the imgpro unit 0x9c600000, whose model S-IMGPRO computes the fill but whose end the request waits for, which rec_jpeg_exec run in the lab's call, outside REC_IMAGE's task, cannot reach (lab time does not move in that call while every task waits): X under camapp 3, all tasks blocked; docs/hle-gaps.md 4.3.1) writes the value its caller gives; no thumbnail is made (IFD1's length 0) (src/lab/rec.mjs)",
  "H-TAKEINIT": "(--take probe, E143) TAKE_FUNC's module init (0x502ccff8, USTART's call at 0x50024c2d) natively before the application starts, after USTART2's stage word 0xa32d6d58 is set to 1 as USTART2 sets it (0x5012abef; TAKE_FUNC_CP's start polls it), then TAKE_FUNC (task 105) and TAKE_FUNC_CP (task 106) started with act_tsk as USTART starts them after the init; the application's requests to TAKE_FUNC's queue (0x5e) then go to it natively, the synchronous ones included, and leave S-MODACK (src/lab/take.mjs; docs/hle-gaps.md 4.1.4)",
  "S-TAKEREQ": "(--take probe, E143) the recording stand-in for every queue TAKE_FUNC and TAKE_FUNC_CP post to whose reader the lab does not run (BC_EXEC and CPU 2's MOV_COMMAND, SDET_EXEC, WB_MOV; TAKE_EXPOSE's and TAKE_POWER_MANAGER's queues go natively, H-TAKENBINIT, STB_EXTERNAL's, H-STBINIT, and TAKE_FOCUS's, H-TAKEFOCUS): each request is recorded (queue, command, parameter, token, synchronous or not, the sender) and dropped, and answered only where TAKE waits: a synchronous request returns the status 0 (TAKE_FUNC's own 0x502ce86d returns the reply's u16 status, 0x502ce8ba); a request whose reply queue is TAKE_FUNC_CP_POST (0x61) gets {status 0, its token, 0} there after the step, which TAKE_FUNC_CP's start sequence clears from its pending bits (0x502cdad7..0x502cdae3); BC_EXEC's request is followed by TAKE's own completion callback in its parameter (0x502cdc0b, which posts token 0x80 to 0x61; that BC calls it is I); a request with no reply queue is not answered. Posts to TAKE's own queues, to LENS_EXEC (the native lens) and TAKE's replies to its requesters go natively and are recorded. Any other queue throws (src/lab/take.mjs; docs/hle-gaps.md 4.1.4)",
  "S-TAKECAM": "(--take probe, E143) the camera driver's request switch (cam.c, 0x502a4a46) from TAKE's tasks, whose init the lab does not run (its request pool 0x6299726c is empty: request 148's handler failed its allocation and logged 0x0a103000, X): TAKE_FUNC_CP's start makes requests 148 and 6 and waits on flag TAKE_CAM_EVENT bit 1 for each (and, under camapp 3 with H-TAKEFOCUS, TAKE_MAIN's RdyFcsRdy1 request 144, 0x503c2e21, docs/hle-gaps.md 4.1.8); the stand-in records each, returns 0 and after the step calls the request's completion callback (+72, TAKE's 0x502cd4d0) natively with the status 0 and the request, as the driver calls it (0x502a4b92..0x502a4b96). Nothing the driver would do to the sensor is done (src/lab/take.mjs; docs/hle-gaps.md 4.1.4)",
  "S-TAKEUSF": "(--take probe, E143) the dust filter's gate-on API (0x50064a69, 'USF GATE CONTROL') from TAKE's tasks: TAKE_FUNC_CP's start asks it with its record {callback 0x502cdc97, 0} and waits on flag TAKE_FUNC_CP bit 1, which that callback's deferred count sets; the API drives the filter through the timer block at 0x9b880000, which the lab does not model. The stand-in records the call and after the step calls the record's callback natively with the status 0 and the record, as the filter's completion does (0x50064d40..0x50064d5b). The filter does not run (src/lab/take.mjs; docs/hle-gaps.md 4.1.4)",
  "H-TAKEMAIN": "(--take probe, E143) TAKE_MAIN's module init (0x50399619, the boot stage 0x501e8e84's call at 0x501e8f7b: TAKE_EXEC 0x5a and TAKE_POST 0x63 bound to its flag's bits 2 and 4, its context 0x62a3f018.. set) natively after H-TAKEINIT, then TAKE_MAIN (task 107) and TAKE_MAIN_CP (task 114) started with act_tsk as the boot stage 0x501e94a5 starts them (0x501e9bbf, 0x501e9bcd; TAKE_PROXY, started there next, stays dormant). TAKE_EXEC leaves S-MODACK, so the take requests go to TAKE_MAIN natively, and what TAKE_MAIN (its mailbox, TAKE_EXEC, TAKE_POST) and TAKE_MAIN_CP take joins the probe's record. S-TAKEREQ takes TAKE_MAIN's requests as it takes TAKE_FUNC's, with CPU 3's FACE_FD (0x3002) among its queues, and answers a request whose reply queue is TAKE_POST with {status 0, its token, 0} there after the step, which TAKE_MAIN looks up by the token in its state's reply table (0x50399971..0x50399a86), only where that handler was read: TAKE_FOCUS's 0x300 with token 1 (RdyFcsRdy1's 0x503c2e8d reads only the status; with H-TAKEFOCUS, which every probe runs, that request goes to TAKE_FOCUS natively and is not answered here); any other such request throws; TAKE's synchronous request 0x502ce86d from TAKE_MAIN to TAKE_FUNC runs natively (src/lab/take.mjs; docs/hle-gaps.md 4.1.7)",
  "H-TAKEFOCUS": "(--take probe, E143) TAKE_FOCUS natively after H-TAKEMAIN: its interface's init (0x506ea9d7, USTART2's stage 0x501e8e84 at 0x501e9088: its context pointer, the ready byte 0xa33d955c cleared, its UI_IN edge callback 0x506eac7a) and its module's (0x509a0e37, the boot stage 0x501e94a5 at 0x501e9541: the ready byte set to 1), then TAKE_FOCUS (task 104) started with act_tsk as that stage starts it (0x501e964f); the AF library's own init 0x508bede6 does not run. TAKE_FOCUS's queue (0x5d) leaves S-TAKEREQ: its commands (in the lab's runs MODE_START 0, MODE_UPDATE 2, RELEASE_READY_START 0x300 and RELEASE_IDLE_READY 0x403) run natively, it replies itself and calls TAKE_MAIN's callbacks itself; with the ready byte 1 its request API 0x506eab1f sends synchronously through the kernel, which runs natively. TAKE's event post 0x502ce5e6 to the application's queue 6 and TAKE_MAIN's reply to the take request's requester (0x50399c4f) go natively and are recorded (src/lab/take.mjs; docs/hle-gaps.md 4.1.8)",
  "S-THRTAKEOVER": "(--take probe under control camapp 3, E143) the through image capability's state word (0x60362b38, CapThr_ThroughImage's entryState) set to 0x01010202 through its own setter 0x50bcecb8 before the application starts, as the boot take-over (API 70405, 0x50adffda) sets it together with module 9's state 2 (0x50ae0044..0x50ae0055), the state S-TAKEOVER writes alone (the rest of that path, 0x50ae005c..0x50ae007b, runs in neither); that the camera's boot takes the through image over is S-TAKEOVER's assumption. The sequence parts take a half press only while the state's top byte is 1 (the S1 guard 0x50c8d4a4 -> 0x50bcdef7); with the word's static 0x02010202 every S1 was refused (X) (src/lab/take.mjs; docs/hle-gaps.md 4.1.7)",
  "S-MDACTRL": "(a body with the file system and its HLS side: E143, E146) the function component's part of a Card Formatting from the menu (CmpCst_Function, an HLS component that does not run): at the media control's start (TRA 1511, command 1, which S-TRAACK answers) api_media's format runs natively, so the file module formats the card from the firmware's own request; the file module's progress events become the component's progress notifications (1513, its own percent) and its reply the component's end: the slots' format flags, 1513 at 100, 697 and the result 1514 (kind 72), which takes the application from Busy back to the menu (E143's ids; E146's request, progress and result are 1509, 1511 and 1512); before the result the DCF numbering mount again, for the next file number (I). The notifications are the firmware's own event objects through the reception's synchronous slot (the component's asynchronous one needs the OXF main thread, which does not run, I). Any other media control command or an error status stops the session (docs/hle-gaps.md 4.8.3)",
  "S-MEDIA": "(a body with the file system and its HLS side: E143, E146) the media manager's part of a card's removal and insertion (CapMed_MediaManager, an HLS component that does not run): the card switch changes as a body's does (UI_IN decodes it natively and calls the file layer's own callback); on its event the stand-in reads the switch's level natively and, for a card out (level 1, I), sets the slot's HLS mount state to unmounted with the firmware's setter, sends the DCF process's card out and the sdmem card-info clear (I: its sender is not read) and the notification 711 {kind, 0, 0}; for a card in, 711 {kind, 1, 0}, S-CARD's insertion requests, the mount state mounted and 711 {kind, 1, 2} and {kind, 1, 8}. The application's media control turns them into its card-out, card-in and mount events natively; which notifications the manager sends, and in which order, is I (docs/hle-gaps.md 4.8.3)",
  "H-DPCINIT": "(a board with the deferred-call triggers, src/fw/board.mjs dpc) the deferred-call init (the boot head's, not run by the lab; E143 0x50050279, src/fw/facts.mjs deferredCalls) natively at the play bring-up, or with the native lens (src/fw/models.mjs lens_native) before the lens init: the six rings cleared, the six trigger words written 0 and their IRQs attached (E143 53..58, the E144 family 29..34); a post (the lens's power and detect paths, E132's first serial request) writes 1 to its trigger word (src/dev/dpc.mjs), which raises the IRQ, taken at the next idle point",
  "H-LENSINIT": "(a body with the native lens: E143, E146, E147; the body's addresses read by src/fw/facts.mjs lensDriver, E143's here) the lens module init 0x502a5d10 (boot call 0x50024ab6), then USTART_L's lens data cache load 0x502a6371 and lens task variables 0x502a5dff natively before the application starts, the cache load after the module init (I: the init clears the cache's ready byte the load sets and the lens start waits on), and LENS_MAIN, LENS_COMMAND and LENS_ASKDATA started with act_tsk",
  "S-LENSNAND": "(a body with the native lens) the lens data caches' NAND (7 areas of 256 KiB from 0x416e0000, E143's flash area table 0x602a4a24; the body's read by src/fw/facts.mjs lensDriver) behind the NAND access the card's S-FSNAND serves: it reads erased, a camera that never cached a lens; without H-RESINIT (E146, E147, a host without env.nand) a read of no bytes (the lens tables' flash area, whose extent the flash area init, not run, would set) reads nothing",
  "H-RESINIT": "(a body with MODELS res_nand: E143; a host that gives the NAND, env.nand) USTART_L's resource loader 0x501a8ca0 natively at the play bring-up, before H-LENSINIT's lens data cache load: the resource API's tables (the resource block's types 0 and 1, the images' 3, the sounds' 2, the large data's 0x8000 and its twelve sub-tables 0x8001..0x800f) read from the NAND through S-RESNAND; then USTART_L's load of sound 0 into 0xa4000000 (on the erased area its size wraps, res_read logs 0x1f000003 and leaves the descriptor {0, 0}, as on a camera with an erased area; with a sound area, S-SOUNDRES's or the host's, it loads sound 0). The lab runs that load right after the loader, where USTART_L runs it after the lens data cache load, res_read(11, 0) and a wait on the byte (0xa32df1c0) whose meaning is ? (0x50024323..0x50024336, D): an order the lab chose, H-; the two touch different state (docs/hle-gaps.md 4.5)",
  "S-RESNAND": "(with H-RESINIT) the NAND behind the access the card's S-FSNAND serves, below S-LENSNAND: the update's blocks at their load addresses as the camera stores them, head + descrambled body + tail, from the NAND extract the host keeps (unpacked/<code> on node, OPFS in the browser: the heads, the indexes and the records of at most 64 KiB), the resource block's body from the lab's own copy; the camera's sound resources at 0x4e420000 (factory data, not in the update): the host's image (env.soundArea), else S-SOUNDRES's lab-made one where the audio hardware runs (--audio auto on E143), else erased; the firmware's writes and erases inside the flash guard's window 0x4e420000..0x4e460000 kept for the session; a read anywhere up to the RAM log at 0x4e820000 served from the area, erased past the window and the image (res_read of type 2 reads an entry's size + 1024 bytes, past the last entry's end), and an access across the area's start or that address refused",
  "S-SOUNDRES": "(E143 with the audio hardware, --audio auto, and no env.soundArea) a LAB-MADE sound area served by S-RESNAND in the camera's factory area's place (src/lab/soundres.mjs): the TG-7's format (an OE head at 0x4e420000, 16-byte entries, 512-aligned RIFF WAVE files) with one sound, id 0, the AF confirmation, which playAfSound asks for: two 52 ms bursts of 2.7 kHz, 24 ms apart, synthesized by the lab at a quarter of full scale, 48 kHz 16-bit stereo, named in its INFO chunk as lab-made and keyed PRM_AUD_AFOK_VOL as the TG-7's AF sound is (X), so that the driver plays it directly from its buffer; its samples start 16-byte aligned (the port's slot addresses hold the address >> 4, D). What a listener hears at S1 is this beep, not the camera's: the OM-1's own sounds are factory data the lab has no copy of, and nothing about this one is measured from a camera (I). Ids 1..5 (background music, aud_debug's) are left out, the index zero-padded as the TG-7's is (X); no lab input asks for them",
  "H-LENSON": "(a body with the native lens) TAKE_FUNC's request to LENS_EXEC at the camera's start (command 1, 0x502cd9c7..0x502cd9f2), posted by the lab with no reply queue (TAKE_FUNC, which would take the reply, does not run); LENS_MAIN's camera-on then runs the lens's detect, power-on and start natively, with the lens on the mount: its detect pin low and the lock pin switch LLPSW (0x121c) released in the idle image (its bit the body's UI_IN tables')",
  "S-LENSMCU": "(a body with the native lens) the lens's microcontroller at the far end of the lens serial controller (src/lab/lensmcu.mjs): the frames of the lens's start and its state poll answered in the layouts their parsers read (docs/hle-gaps.md 4.4.2), the values of the 12-40mm F2.8 PRO S-LENS wrote (its ID, name, zoom steps' focal lengths, apertures; I), the zoom step S-SCENE's focal length; a type-1 frame (a0 b0 [fe xx], a0 b1 [00 00]: the request 0x502b7e8a builds, data count 0, its completion 0x502b7efe reads only the status; the AF library's mode set 0x50974553 sends it, docs/hle-gaps.md 4.1.8) is completed with no reply; a frame it does not know stops the session naming it",
  "A-LENSSSC-1": "(a body with the native lens) a lens frame is sent and answered at once, in zero lab time: the controller's interrupt is taken at the next idle point",
  "A-LENSMCU-1": "(a body with the native lens) the lens's fields the lab has no value for are 0: its flags (no optional functions), function words, tables beyond the characteristics S-LENS wrote, serial number and firmware version",
  "A-LENSMCU-2": "(a body with the native lens) the lens reports the protocol version 0x130a, the newest the driver tests for, with no block mode; the 12-40's own is ?",
  "A-LENSMCU-3": "(a body with the native lens) one byte a zoom step in the table of id 71 (the driver logs a reply of class 0xcx with no data as an error)",
  "A-DPC-1": "(a board with the deferred-call triggers) bit 0 of a deferred-call trigger word is its IRQ's level: high until the word is written 0 or, for the first two IRQs (E143 53 and 54), until their handler disables the IRQ (the next post enables it again)",
  "A-EMS1-1": "(E143, with S-EMS1) a run of the EMS1 engine takes 1 ms of lab time from its start to its completion interrupt (IRQ 276); the engine's time per frame is not known, and its driver waits for the interrupt (with a 1 s watchdog), so only the lab's pace depends on it",
  "A-PDT-1": "(E143, with S-PDT) a run of the PDT or the TRC engine takes 2 ms of lab time from its start to its completion interrupt (IRQ 279 or 278); neither engine's time per frame is known, and their drivers wait for the interrupt, so only the lab's pace depends on it",
  "A-DML-1": "(E143, with S-DML) a run of the DML engine takes 10 ms of lab time from its start to its completion interrupt (IRQ 285); the engine's time per frame is not known, and MDET waits for the interrupt without a timeout, so only the lab's pace depends on it",
  "H-ACCINIT": "(a body with the accelerometer, src/fw/models.mjs acc) the ACC module init natively in the boot's place, before the application starts: its pointers, the axis references, the temperature and offset parameters from the store, and ACC_MAIN (task 121) started; its device part (the sensor's data-ready pin and the register API's kernel objects) is stepped over. ACC_MAIN then runs natively: the probe once, every 80 ms the cache copy and the correction (docs/hle-gaps.md 4.7.3)",
  "S-ACCREG": "(a body with the accelerometer) the sensor's register file at its register API (open, read, write, close): the probe's WHO_AM_I read answered with the value the probe wants and its two set-up writes kept; any other access stops the session (the sample reads go through ACC_SENS_MAIN, which does not run)",
  "S-ACCSAMPLE": "(a body with the accelerometer) the sensor, its data-ready pin, the sampler task ACC_SENS_MAIN and its transfer: before each of ACC_MAIN's cache copies, one new sample stored as the read's completion stores it (the accelerometer's three halfwords and the temperature word, the counter + 1). The sample is the firmware's pose-0 reference for the level camera, turned by the session's tilt input (roll, pitch in degrees)",
  "H-SLOPEINIT": "(a body with the accelerometer) PER_SLOPE's init natively before the application starts: its flag, its state and task 78 started; the GUI's startLevel then runs it natively (every 20 ms the remap, mg, the asin table, the stability test, the results the gauge's getter reads and its event to the application)",
  "A-ACC-1": "(a body with the accelerometer) the sensor reads 25.0 degC (the temperature word 0); the temperature compensation is off on the lab's blank factory data anyway (calibration type 255)",
  "A-ACC-2": "(a body with the accelerometer) one new sample per ACC_MAIN cycle (80 ms; the probe's CTRL1_XL write 0x10 is 12.5 Hz by ST's register map, I), and, without --rotate on, only tilts that keep the body's y axis dominant (roll and pitch within 45 degrees): PER_ROTATE, which would turn the camera's orientation, does not run then, so the orientation stays 0. With --rotate on the tilt takes any attitude (roll within 180, pitch within 90 degrees)",
"H-ROTINIT": "(--rotate on, E143 and E146) PER_ROTATE's init natively in the boot's place, right after PER_SLOPE's as the boot calls it: its limits, the orientation 0, its state active and task 59 started. PER_ROTATE then runs natively every 100 ms: the corrected sample, the remap, mg, the magnitude gate (600..1400 mg), the orientation with its own hysteresis (portrait past 50 degrees of roll and back below 40, the lens up or down past 60 degrees of pitch and back below 50) and, on a change, event 0x4020310; the GUI then reads the orientation through its getter and lays the level gauge out for portrait natively (docs/hle-gaps.md 4.7.3)",
  "A-ACC-3": "(a body with the accelerometer) the tilt input's roll is the angle the gauge's getter reads back as its horizon, its pitch three times the getter's vertical (the getter divides by 3, D); which physical direction each sign is has no camera evidence",
  "H-G4SET": "a group-4 input (HDMI, CEC keys, lens key, lens MF, 0x0400, grip 0x2003) is the firmware's own group-4 producer 0x5014d537(code, 0 = bit at its polarity / 1 = the other level) called from the lab task (its callers, e.g. the display driver's HDMI report 0x501d69d8, do not run, but for that report with --hdmi on, where fw_0501 is refused): it keeps UI_IN's own image 0x629887e4, which UI_IN's LLPSW branch also pushes (0x5014c9a4), so group 4 has one image",
  "H-DIALSTEP": "a dial detent is one call of the firmware's counter writer 0x5014bae6(dial id, +1 or -1) from the lab task (its callers, the command dispatcher 0x5100af66 and the encoder reader 0x5014bd60 whose position read 0x50059fa4 is not modelled, do not run); UI_IN's dial step then posts the dial id natively. A detent whose counter word the GUI does not read is reported (dial_unread) and the word cleared",
  "H-JSINJECT": "the multi-selector is UI_IN's code entry 0x5014c12e from the lab task: the press 0x1235 (0 press / 1 release), the directions 0x1234 (0..7, 8 centre; one direction at a time, a second one through the centre). The raw producer of 0x1234/0x1235 is ?; the decoder, the post and the application's direction query run natively",
  "H-TOUCHGAP": "touch samples are served at least 20 ms of lab time after the previous one ended: the driver queues gestures for 10 ms after a PRESS into 5 unchecked slots (0x501e487b..b2, timer 0x501e48c2..df) and three taps with no lab time between them overrun it (fault at 0x501e4a13, X). With --idle wall also at least the user's gap after the lab time the previous sample ran at (the page's timestamps, else arrival times): inside one contact up to 2 s, from a lift to the next down up to 0.32 s. The driver takes a second tap 287.0 ms after the lift as DCLICK and 300.3 ms after it as CLICK (X; where it keeps the window is ?), so a separate tap stays a tap and a double tap stays one; a tap costs at most 0.32 s of lab time more than its hold. The touch controller's report rate is ?",
  "S-DISPQ": "the display manager's asynchronous DISPLAY request (OlyQeWr to the DISPLAY queue 0x88 from 0x503eba00, DISPLAY cmd 18 on every shooting-screen transition, X) runs the DISPLAY loop 0x501c3035 at once, as the synchronous sends do (the DISPLAY task, static id 54, priority 26, outranks the GUI and does not run as a task in the labs); the loop's replies to queue 6 (0x501c48bf, OlyQeWr at 0x501c490c / 0x501c496d, returning to 0x501c4913 / 0x501c4974), whose reader, the camera application's task 58, does not run, are recorded and return E_OK. Without it the queue fills and the 30th request blocks the GUI for good (X). Any other send to the DISPLAY queue is an error",
  "S-BGDRAW": "0x50b3dcca returns d0 = 0 to two GUI callers (return addresses 0x510c9a07: shooting screen, direct WB / Picture Mode, dial-direct; 0x510c9cf5: playback), whose paint stays held without it; its other callers (menu entry, menu close) run it natively as every other lab does",
  "S-CAFWD": "(with S-LENS, where the camera application's touch path is off) the GUI's touch forward to the camera (CA caller vt+4 0x51084994 with event 35) is recorded and returns d0 = 0 without calling (this+212) vt+8; every other event runs natively. With the native lens the application forwards the touches and takes this answer itself (docs/hle-gaps.md 4.4.2)",
  "S-TOUCHMAP": "(with S-LENS) camera-application stand-in: HFW touch status -> GUI touch kind by name (225 TOUCH 1, 226 LONG 2, 227 RELEASE 3, 228 TAP 4, 230 DOUBLE TAP 5, 229 SLIDE 6, 300 FLICK -> 7, I), posted as the index of the touch message 0x9100 in the build's event map (E143 109, E137, E142, E140, E125, E130, E133, E118, E120, E122 107); with the native lens the application posts them itself",
  "H-TPINIT": "the boot call of touch init 0x501e3dca (from 0x50024ca6) from the lab task, then act_tsk(83); before the start's display open on a build whose touch driver waits for the INT (fact touch_int: the E144 family, whose open arms the driver after that wait and whose init clears it, and the E118 family, whose display open posts the touch task's power-up to the queue the init joins to the task)",
  "H-TPSTART": "TP_OPEN 0x501e40da(HFW callback 0x60b97e80, 0) and the gesture mask 0x501e41d1(0x11f1) from the lab task (the camera application's own start call is not traced)",
  "S-TPREG": "the touch controller read 0x501e4f2a answered by the controller at the slave it reads (src/lab/touchpanel.mjs): slave 0x70 (E143's) from register 0x02 out of an 11-byte image: count, event<<6|x>>8, x, id<<4|y>>8, y, 0, 0, then the second point as event 3 / 0xfff (no point, the executed probes' bytes); raw = (x, 599 - y), the driver's flip 0x501e44c0 reports (x, y); slave 0x48 (the E144 and E118 families') a 10-byte report at 0x0000 (touches, event 2 down / 3 move / 1 tap / 0 release, ids, the point's 12-bit x and y in panel pixels) and the release bit at 0x1c0a (I), and the controller's version at 0x1c14 as c4 00 (E118's driver reads 0xc400, the version it goes on from without downloading the controller's firmware; I)",
  "S-TPINT": "the touch interrupt: OlyEvSt(touch flag, 1) from the lab task, what the pin-110 callback 0x501e5233 does with iOlyEvSt",
  "S-GPIO-TP": "lab-stub page 0x9b880000 opened; pins 48, 49, 108 (0x9b880e00, 0x9b880e40, 0x9b883e80, table 0x60025ff8) read level 1 (bit 4), the only level at which the driver accepts a touch (0x501e4858..79, 0x501e4bbb..df); what the pins are is ?",
  "A-USLAB": "the us clock (E143's channel 33, the board's us channel) counts lab microseconds from the reset (timer window USMODE = 1, the default): one count = 1 us (A-TMR-2). A CPU read gets at least one count more than the read before, so a busy wait inside one lab instant still ends; lab time later passing those counts does not count them again",
  "H-USCOUNT": "(--us-clock reads) the us clock counts one per CPU read from the reset and ignores lab time (timer window USMODE = 0): a wait on it lasts as many reads as its microseconds, however much lab time passes",
  "H-POWER": "the power lever's off is decoded natively (UI_IN's group 0 through the SCPU's ports, H-SCPUPORT) and the application takes its code; on a body that runs its power-off (E143, E146, E147: src/fw/models.mjs power_native, at the addresses src/fw/facts.mjs powerOff reads) the lab then runs the firmware's own power-off from the HFW's shutDown (S-SHUTDOWN, src/lab/power.mjs) and ends the session at its last write, 127 into the SCPU window's request word, after the sub-CPU's 0x85 power-off; elsewhere it closes the session at once. On brings up a new one; the camera's power-on sequence is not run",
  "H-DRVINIT": "(a body whose reset path runs a table of early driver inits, src/fw/models.mjs boot_drivers: the E118 family's) the table natively at the start of the timer boot steps, which the lab, entering at the kernel, would skip: the GIO pins' configuration and the board-id read (into the lab stub's pages), and the timer pool the software-timer init allocates from",
  "H-MMINIT": "(a body whose boot chain calls a module init of its own at stage 3, src/fw/facts.mjs mmInit: the E118 family's) that init natively after the memory managers' constructors, which the lab, ending the init task, would skip: on E122 two slot managers whose methods the application's property reads reach",
  "A-PERIOD": "(a body whose vtotal functions return constants with no frame period getter after them, src/fw/models.mjs frame_period_us: the E118 family's) the TFT's and the EVF's frame period, which the build keeps nowhere the lab can read, is assumed: E143's TFT period of 16683 us. It sets only the lab clock's line time",
  "H-PWRTASK": "(a body with the power task, src/fw/facts.mjs powerTask) the power task, which the boot starts, started with act_tsk at the play bring-up: it runs the power module's init, the internal charger's with it (its IIC channel's configuration and completion flag), and waits on its queue",
  "H-SIOMAP": "(a body with PER_SIO devices, src/fw/models.mjs sio_devices: E129, E132; with --take probe on E143 too, for the hot shoe's channel 11, index 6, if nothing set the map: S-HOTSHOE, src/lab/shoe.mjs) PER_SIO's channel map set at the play bring-up by the firmware's own setter (src/fw/facts.mjs sioDriver map_init), the end of PER_SIO's channel init, which the boot runs and the lab does not: each channel then reaches its own serial controller (on the TG-5s channel 9 index 7, the panel's channel 2 index 2 and the IIC bus's channel 3 index 3, their register blocks lab-stub pages that keep what is written, src/fw/models.mjs board stub_pages); before, every channel's index was read from low memory, and the channels shared one controller's open flag (D)",
  "S-SIOIIC": "(a body with PER_SIO devices) PER_SIO's serial controller for the channels a device sits on, at its driver's transfer and receive starts (src/lab/sio.mjs, src/fw/facts.mjs sioDriver): PER_SIO's IIC layer and the driver's completion dispatch run natively; a transfer's bytes are split at the transfer's restart list into IIC segments, each opened by its address byte, and handed to the device (writes, and a last read of the kept receive's count); the transfer ends at the MN's next idle point (A-SIOIIC-1) in interrupt context: the restart list cleared, the transfer's then the receive's completion dispatched with status 0, the received bytes written first. A polled transfer, a read segment not last or carrying data, a receive without a read stop the session; the other channels' starts run natively",
  "A-SIOIIC-1": "(a body with PER_SIO devices) a transfer on a served channel takes no bus time: it ends at the MN's next idle point (the TG-5 charger's 3 bytes at 400 kHz take about 70 us on the bus)",
  "S-CHARGER": "(E129, E132) the TG-5's internal charger at address 0x1b on PER_SIO's channel 9 (src/lab/charger.mjs): registers 0, 1 and 2, the ones the charger request's table writes, keep what is written (I: the request reads each write back and compares), a read answers the register the write segment before it named; a read of a register not written in the session (its value on the camera is ?), another address, register or length stops the session. The chip is not named in the image (?)",
  "H-AUDSTART": "(--audio auto or on, E143) AUD_MAIN, the audio driver's main task, which the boot's USTART2 starts (0x501e950b), started natively at the play bring-up with act_tsk (src/lab/audiohw.mjs): its init, the CPU 2 starts S-AUDCPU2 answers, the driver's init (the SCA's and the audio port's, which attach IRQ 45 and IRQ 43 natively), the starts of AUD_COPY_DATA and AUD_WATCH_DOG (allowed) and its wait on its queue AUD_EXEC, which then takes its commands natively (S-MODACK leaves the queue, synchronous sends included, to it). Before the start the lab sets the image's stage 6 bit (0xa32df1f4 bit 5), which AUD_MAIN waits for and the boot's per-segment step would set (the lab's image holds every stage); the bit stays set for the session, so any other code that reads stage 6 sees it set too. USTART2's 0x501553fa just before is the still and power modules' step, not run (D)",
  "S-AUDCPU2": "(--audio auto or on, E143) CPU 2 is not in the lab: AUD_MAIN's starts of AUD_WAKEUP (0x2017) and AUD_LEVEL_MONITOR (0x200e) on CPU 2 (OlyTaStCpu 0x5002d325, cpu_conn kind 9) are answered with E_OK from AUD_MAIN's task, and for AUD_WAKEUP the stand-in posts what that task posts when it ends, 0x50035afd(0, 0x60a83d95, 0) (ring [0][2], bank-0's bit, as S-CPU2's reply); CPU 0 takes IRQ 324 natively and the call sets flag 0xf9, which AUD_MAIN waits for. The sound IC's power-on list AUD_WAKEUP runs on CPU 2 (0x50a62e27) is not run; any other start of those ids is an error, any other OlyTaStCpu call runs natively. With --cpu2 native AUD_LEVEL_MONITOR's start runs natively (cpu_conn kind 9 to CPU 2's CPUCONN, whose proxy starts it on CPU 2) and only AUD_WAKEUP's is answered",
  "S-WM8946": "(--audio auto or on, E143) the sound IC, a Wolfson WM8946 (the firmware's name), at the far end of PER_SIO's channel 14 (src/lab/wm8946.mjs), served at PER_SIO's channel API (open, configure, transfer, close) over S-SIO2's hooks: its register access exec_data 0x50a632c5 writes 4-byte frames {address, data} and reads with 2 bytes sent and 2 received (bit 7 of the first set); a 16-bit register file keeps what is written and answers a read with it (a read of a register not written in the session, its value on the camera ?, or another frame stops the session); a transfer ends at the MN's next idle point in interrupt context (A-SIOIIC-1's rule). Not S-SIOIIC's seam: on E143 PER_SIO's own configure writes the channel's controller registers, which the lab does not model (X). The codec's volume registers are kept, not applied to the PCM",
  "A-AUDIO-1": "(--audio auto or on, E143) the audio serial port (src/dev/audio.mjs), TX only: an armed slot plays for its length / (48000 x 4) s of lab time (768 bytes: 4 ms), fetched from memory as it starts, from its address register's value << 4; each slot's end sets its done bit and bit 5 (one IRQ 43) and starts the other slot if armed, else the port underruns and stops; a slot armed with length 0 is empty: TX ends there and the port clears TX enable itself, so the ISR stops at the interrupt of the slot before it (the driver's direct play, the AF sound's, arms its slot B so, does not reach the driver's own TX disable and waits for that stop's TX done callback in command_play_end, D; that the hardware ends TX so is I, and that it raises an interrupt for the empty slot instead is not excluded, ?); TX enable rising sets bit 4; clearing TX run lets the playing slot play out with no interrupt, and a new start while it plays cuts it there; the status is write 1 to clear; +0x20 bit 24, which the port enable writes, is storage. The bit meanings are I from the driver's code (the ISR 0x50aa90e2, the re-arm 0x50aa8ef3, the open 0x50aa9379); the formats are the two TX templates the driver writes for a 48 kHz 16-bit stereo WAV, the copy task's and the direct play's (X; they differ in +0x30 bit 6, whose role is ?), any other stops the session; RX and an SCA start stop the session. The played slots go to the host as PCM events of source 'native'",
  "H-AUDTIME": "(--audio auto or on, E143) while the audio port plays, the lab's stand-ins that move lab time in one jump while a task holds the CPU (the vsync wait's run_to_frame and the sleeps' advance, src/lab/display.mjs) go from clock event to clock event and run the kernel's deliveries after each, IRQ 43's handler among them, in interrupt context: the port's re-arm keeps pace (X: one 16.7 ms jump past several slot ends left it to underrun). The copy task AUD_COPY_DATA runs once the stand-in's task lets go, up to a frame later, within the ring's 8 periods (32 ms) of lead",
  "H-UIOUTSTART": "(a body with MODELS ui_out: E134, E143) UI_OUT, the module of the camera's lamps (on E143 its operation sounds too), which the boot starts: its init natively at the play bring-up, then act_tsk of its static task, which waits on its queues and takes the lamps' and the sounds' requests natively; E134's file layer's card access lamp requests (sends without a timeout to that queue) then go through, and E143's AF beep (S-AFLOCK) reaches its sound request 0x5014f7e0, which looks the sound up in the type-2 table (H-RESINIT; S-SOUNDRES's lab-made area where the audio hardware runs, else erased: then nothing plays) and sends the audio commands to AUD_EXEC (AUD_MAIN's with the audio hardware, else S-MODACK's), and its end handler releases the sound at the driver's post_end; its second queue, UI_OUT_EXEC, which it answers itself, is not S-MODACK's",
  "S-BOOTKEY": "UI_IN's boot key (src/fw/facts.mjs bootState), which its module init records from the sub-CPU's wake factor (not run: H-UIINRING), is the power switch's code 0x000c, set before UI_IN starts: the camera started by its power lever or button, which the camera application's wake-up judgement takes for API_WUI_POWER_BUTTON (D); at 0 it took a battery insertion, and E133 started the boot service that creates no GUI (X; docs/model-survey.md)",
  "S-BOOTSTAGE": "the boot's first stage readied: bit 0 of the stages' ready word (src/fw/facts.mjs bootState) set before the settings store's start, as the boot's stage step for stage 1, which the lab does not run, would set it; the image holds every stage's code, the step's other work is not done and the later stages stay unset. E129's settings flash read waits for it (D; docs/model-survey.md)",
  "S-SHUTDOWN": "(E143, E146, E147) the HLS camera-common component (CmpCCom_CameraCommonComponent), which turns the lever's EV_POWER_SW_OFF into the shutdown, is not created in the lab: the lab calls the HFW's CameraCommon object's shutDown(API_SHUTDOWN_NORMAL, API_SHUTDOWN_REASON_BUTTON) through its vtable, as the shell's \"sdk api shutdown\" does, on the lab task in lab time; from there the firmware runs natively: OlyHfwPower's startShutDown, the settings' save, the RAM log's save, the file module's power-off, api_system's power-off sequence with the IO expanders' commands (none on E147), the SCPU window's ports and wake word, the sub-CPU's 0x85 {1} over the link, and 127 into the window's request word, where the session ends (docs/hle-gaps.md 4.7.4). That the lever's reason is BUTTON is I",
  "H-PWRSTART": "(E143, E146, E147) the power manager (PWR_MAIN) started natively at the play bring-up as the boot starter would start it: its init, which reads the sub-CPU's PC13 (0x82 {45}) and syncs with it (0x12 {5}, answered by the sub-CPU's message 0x12 {5}), then act_tsk of its static task; it then waits for its queue's messages",
  "S-IOEXP": "(E143, E146) the IO expanders' tasks (PER_IOEXP, PER_IOEXP_PBH) do not run (their PER_SIO channels and chips are not modelled): each request their APIs post is completed at the next idle point as the task would complete it, by its completion flag (a request without data) or the GIO extension's write's callback; what the expanders' pins do is not modelled, and any other request stops the session",
  "S-PWRLOG": "(E143, E146, E147) the power-off's save of its RAM log (2 MiB to its own NAND area) is answered done and not kept: the NAND controller is not modelled",
  "H-SCPUPOLL": "(E143, E146, E147) after its power-off 0x85 the MN polls pin 102 in a loop without an idle point until the sub-CPU drops it (it does as it leaves steady, D): at each poll the sub-CPU acts as at an idle point (I: on the camera it runs beside the MN)",
  "H-IDLE": "lab time runs in ELAPSE slices of at most 50 ms paced to the wall clock between inputs",
  "S-HEAP": "the malloc/free stand-ins (src/lab/hle.mjs) with reuse: free() puts a block on a per-size list that malloc() takes from first (the bump allocator of the other labs never reuses and runs out in a play session)",
  "SWITCH": "(M8, live since M10B) DISPLAY cmd 2 OPEN of the other device, H-RESEND (the display manager's palette request 0x503e52c7), H-EYESTATE, H-CONNECT; the camera application re-enters the screen (S-OUTDISP); play no longer runs H-UPDATE (the GUI's own repaint programs the new channel)",
  "S-TAKEOVER": "(M8, every play session since M10B) 0x50ab6299(9, 2) natively once at bring-up: module 9 state 2, the value API 70405 writes on the boot take-over path (0x501e6adb -> 0x50ab2309 -> 0x50adffda, D); no live switch writes it. Scope guard: module 9 may be read (0x50ab5780) only by ChangeOutline (0x50abcfd7 / 0x50abcfe2) for the whole session, any other reader is an error",
  "H-CONNECT": "(M8, generalised in M10B) sendEvent(131, lOutput) after every switch and at an EVF start: lOutput 2 TFT (the sender 0x5105053c's row for devices 2/3, D) and 7 EVF (its INTERNAL_EVF row for device 6, D; its EVF row for device 5 writes 3, whose handler sets connect state 3 and SetLayoutMode(0); which row the camera takes is not traced, 7 is chosen because its handler 0x510c6c27 sets connect state 5); that the camera sends it after the OPEN is an inference. Checked through the B2 observers: ConnectChangePlay ran, vt+20 returned 0 with no RPC, SetConnectState 2 / 5",
  "H-STOREFIRST": "(PLAYFIX, EVF starts only) harness order, not a firmware stand-in: an EVF start runs the settings store init before the EVF OPEN (MenuLab store_first, M8), closer to boot (settings spec section 4: the registry bootstrap follows the flash read at 0x500093ec). The OPEN registers the eye callback 0x501c6aca(1) -> 0x50050e67 -> 0x500515ed, which reads property 1947 (kind 0x4671): on the firmware's default 1 it deletes the timer; on the empty store it reads 0 and arms a 5000 ms one-shot (0x5005899c, callback 0x500516af) that, through task 16, dims the EVF OSD planes to level 32 (0x501c6a93, debug string \"[EVF] display_bievf_vsc_sio_send_brightness_yakitsuki\"), PLANC 0x40, outside the model (A7; X: every EVF frame failed from lab 5.6 s). TFT starts keep the store init after the OPEN: a store-first TFT OPEN sets CTRL3 bit 6 before play's A15 bracket recorder exists",
  "H-EYESTATE": "(M10B; every switch since fix3) the eye-state setter 0x50050efd(2 EVF / 1 TFT) natively from the lab task, the values the output selector 0x501e7fd8 reads (2 = EVF, 0x501e806c) and the key-script player 0x5100af70..88 passes (D; fix2: until then play passed them the other way round). Stand-in (I): play shows one display and its viewer looks at it, so after every switch, LV included, the eye state is the shown device's; a real LV press does not move the eye, and with property 1947 = 0 and nobody at the finder the EVF OPEN arms the 5 s burn-in one-shot, whose dim (PLANC 0x40) the model cannot draw (A7). The setter deletes that pending one-shot (0x50051658..71). A start leaves the state 0 (not yet sensed). Its publish 0x02022301 returns at the gate 0x5002509e ((0xa31f1d26) != 119), so it does not move the GUI",
  "A15": "(M10B, play only, --a15 auto) the composite may assume A15 when the shown channel's latched CTRL3 is exactly 0x41 and every 0x501e04b7(ch, 0) since the channel's last OPEN was closed by (ch, 1) at the same lab time, none open now; otherwise FEATURE_UNOBSERVED as in every check. CTRL3 bit 6's meaning is unknown",
  "H-AEINIT": "(M10B) the table init 0x50560b29 natively at bring-up (pre-condition: its regions still BSS 0); on the camera the boot sequence reaches it through 0x501e90c4 -> 0x50553649 -> 0x505724cc -> 0x50572574 (D), which the lab does not run. Without it a store write from the Super Control Panel or FUNC_DIRECT on Metering, Drive, ISO, Exposure Comp., Flash Mode or Flash Exposure Comp. faults in the interpolation 0x50563138 (div by zero at 0x5056319c). Its inputs are the F-store objects 420 / 403 (kinds 6730 / 6458), image templates of 0 because the lab has no flash data, so the interpolation returns 0",
  "H-IPIINIT": "(M10B) the inter-CPU init 0x5002ce4d (boot caller 0x5000032b) natively at bring-up: 0x5002de2d clears its 256 x 64 byte pool (pre-condition: still BSS 0), IRQ 324 attached at level 2 for CPUs 0..3 (handler 0x5002d83a for CPU 0) and enabled",
  "A-IPI": "(M10B, emu's model) the banks' +0x808 hold inter-CPU pending bits (a write ORs, a read returns them), +0x80c clears the written bits; bank 0's bits drive IRQ 324. Whether +0x808 ORs or overwrites cannot be observed while the firmware writes single bits",
  "H-CPU2RELEASE": "(--cpu2 native, E143) the two words CPU 2 waits for before its kernel and its init task's starts, which CPU 0 writes in code the lab does not run: the release flag (0xa3258360) = 1 (CPU 0's reset head, 0x50000282..0x50000329) and the tick magic (0x97f00088) = 0x77777777 (CPU 0's init task right after its tick init, 0x5002ccdc; H-BOOTTIME runs that tick init); then the machine's second core leaves reset at CPU 2's entry 0x50008f01, the run-time address CPU 0's reset head writes to 0x98d00144 (src/lab/cpu2.mjs, src/core/cores.mjs; docs/hle-gaps.md 4.6.1)",
  "H-CPU2CACHE": "(--cpu2 native) CPU 2's entry writes 16 to its cache-control word 0x98100808 (0x50008f1a; CPU 0's reset head writes 0x98100008 the same, K-CFLUSH sets bit 4 of 0x98100800); the lab has no caches and the bus window's device knows only 0x98100058, so the store is skipped (docs/hle-gaps.md 4.6.1)",
  "H-CPU2UART": "(--cpu2 native) CPU 2's entry prints its mark \"2\" on the UART (0x50000426 called at 0x50008f37; the UART at 0x98700018, whose free count at 0x9870001c it polls); the lab has no UART, so the call is skipped and the mark recorded (docs/hle-gaps.md 4.6.1)",
  "K-BOOTSYNC2": "(--cpu2 native) CPU 2's part of the kernel's boot ring 0x50015a61 (wait on CPU 3's kick, kick CPU 1, wait on CPU 1, kick CPU 3: cores spec 3.3) returns at once: CPUs 1 and 3 are absent and CPU 0's lab skips its own (K-BOOTSYNC) (docs/hle-gaps.md 4.6.1)",
  "K-STARTBITS": "(--cpu2 native) the kernel-start barrier 0x50012367 runs natively on CPU 2, which ORs its bit into (u16)0x97f00000 and spins until it reads 0xf (kcb[380] = 4 CPUs); before it does, the stand-in ORs in 0xb, the bits of CPU 0 (whose lab owns its first dispatch and never runs the start 0x500119ab) and of CPUs 1 and 3 (absent) (docs/hle-gaps.md 4.6.1)",
  "H-CPU2POLL": "(--cpu2 native) CPU 2's idle command loop (BOOT_CPU2 at priority 70 after 0x500387eb, its head 0x5003883a) reads only the CPU 1..3 command block 0x97f0009c..0x97f00113 between interrupts (D): while its halt word 0x97f000fc[1] is 0, a pass that finds the block as the pass before left it sleeps until a byte of it changes or an interrupt comes, then goes on. While the word is set (BOOT_CPU2's 0x50038666 sets it to 1, D) the stand-in does not apply: each pass halts natively with (0x8040) = 8 (0x50038b04) until an interrupt, whose return goes on through the loop to the next pass's halt (since 2026-11-09, round 2). No CPU 0 writer of the command 0x40002 that clears the word is known, so in the lab's sessions it is not used (src/core/cores.mjs; docs/hle-gaps.md 4.6.1, 4.6.2)",
  "H-CPUCONN0": "(--cpu2 native) CPU 0's CPUCONN_CPU0 (task 0x99) and CPUCALL_CPU0 (0x9a), the servers of the cross-core calls and CREQs other cores make on CPU 0, started with act_tsk before CPU 2's boot as CPU 0's init task starts them (0x5002cd0c..0x5002cd2d), which the lab ends; CPUCONN's proxy for a call from CPU 2 (entry 0x5002cf6e) is allowed. CPU 2's cpu_conn calls on CPU 0 objects (OSD_DRAW_CPU2's replies to the GUI's queue) are then served natively (src/lab/cpu2.mjs; docs/hle-gaps.md 4.6.2)",
  "H-CPU2LOADER": "(--cpu2 native) USTART_L2 (task 0x2013), the overlay loader BOOT_CPU2 starts, returns from its entry at once (to the kernel's task exit). Run natively (the control cpu2-loader) it takes CPU 0's FLASH_CS1 through CPUCONN_CPU0 and stops at the flash DMA it starts for segment 1 (0x50001c4c writes 0x98d00200, not modelled: a bus error, X); its CREQs would then run 0x50024eda, whose per-segment hooks are the segments' static constructor tables (0x501e60ac..0x501e6143, D): on CPU 0 those of segments 2, 6 and 7, which the lab's bring-up already runs (src/lab/osd.mjs mm_ctors, src/lab/menu.mjs CTOR_TABLES), and on CPU 1, which is absent, segment 8's, which the lab does not run. The only readers of its byte flags' addresses are boot code the lab does not run (USTART_L, USTART_L3, 0x501e9e17, 0x501e996c; D, a scan for the addresses) and every segment is in the lab's image. Its last call, the DSP service's load of resource 0x8007 item 17, is not made either: whether code the lab runs depends on it is ? (src/lab/cpu2.mjs; docs/hle-gaps.md 4.6.2)",
  "H-CPU2TASKS": "(--cpu2 native) the CPU 2 tasks CPU 0's boot stages start (0x501e8f09..0x501ea7a9, USTART2..5), started at the play bring-up in the stages' order: the module init each stage calls before the start natively on CPU 0 (WB_MOV's 0x5046aa2b, the call at 0x501e9150, just before it; MVR_MAIN's 0x5045fed3, 0x501e91ee, which binds MVR's queues to its flag 0x2003; for SDET 0x50510afd, 0x501e96a0, an init among SDET's own functions, which the stage calls before the starts of FACE_MAIN on CPU 3 and FACE_BEAUTY on CPU 1, not made, D), then OlyTaSt(id) from the lab task, which goes to CPU 2 natively (cpu_conn kind 9, CPUCONN2's proxy, act_tsk there): WB_MOV 0x200f (0x501e9157), MVR_MAIN 0x2002 (0x501e9233), SDET 0x2010 (0x501e96f1), OSD_DRAW_CPU2 0x2015 (0x501ea04c). Each then waits at its own wait (X). The stages' other steps between are not run, among them MVR_MAIN's site's wait for the byte 0xa32df1be (set by USTART_L and USTART_L3, D) and 0x501e6a7f(2). Under control camapp 3 the GUI's drawHistogram sends to OSD_DRAW_CPU2's queue 0x2013 leave S-MODACK and go to it natively; under camapp 1 and 2 they stay S-MODACK's (E_OK, nothing drawn), since nothing writes the bins they point at there (S-TRAACK answers getHistogramData): they keep 0xdeadbeef, the fill the task creation 0x5002cbe7..0x5002cbf8 writes into a new task's stack (X) (src/lab/cpu2.mjs; docs/hle-gaps.md 4.6.2)",
  "A-CPU2RESET": "(--cpu2 native) CPU 2 leaves reset with PSW 0 and every register 0 but the pc; its entry sets the PSW mask, the sp and the cache control before it uses any of them (D 0x50008f01..0x50008f24), so only an interrupt accepted before its first instruction could tell (docs/hle-gaps.md 4.6.1)",
  "A-COREPAGE": "(--cpu2 native) each core has its own 64 KiB page at 0x00000000 (the system-register page 0x8000..0x8fff: IVAR, GxICR, 0x8040, the core number 0x8050, 0x8070, IAGR 0x8a00; cores spec 3.2, I) and CPU 2 its own local RAM at 0x50000000..0x5000ffff (its early stack 0x500027fc and the 4 KiB window it copies to 0x50002000; cores spec 3.4, I), zero at its reset; CPU 0 keeps the lab's low RAM and flash view there. Which other addresses are per core is ? (docs/hle-gaps.md 4.6.1)",
  "A-COREID": "(--cpu2 native) the core number word (0x8050) of CPU 2's page reads 2 from its reset: no code writes it (cores spec 2, D), so it is the hardware's (docs/hle-gaps.md 4.6.1)",
  "A-INTERLEAVE": "(--cpu2 native) the two cores' order: CPU 0 runs as the harness drives it, and inside its runs CPU 2 takes a turn of up to 2,000 instructions after every 2,000 instructions of CPU 0 (counted across runs); at CPU 0's idle point CPU 2 runs until it sleeps; neither moves lab time (FIDELITY 1.1). The relative speed of the cores is not known (?); boot polls have no timeouts and the rings are FIFO, so any fair order should serve (I) (src/core/cores.mjs; docs/hle-gaps.md 4.6.1)",
  "A-KICK": "(--cpu2 native) a write of 1 to a bank's +0x810 (the kernel's kick, kcb[316]) raises that bank's IRQ 325 until a write of 1 to its +0x814 (IRQ 325's handler 0x50003faf writes it, D); IRQ 325's level register is a bank's +0x514 (the entries write 0x40 there, the INTC inits 0, D); the kicks are recorded. The boot ring that would use it does not run (K-BOOTSYNC2) (docs/hle-gaps.md 4.6.1)",
  "H-CPU2GATE": "(--cpu2 native) CPU 2 accepts an interrupt its bank presents at any instruction boundary its PSW admits (CPU 0 keeps H-IRQGATE's idle point); its presentations and acceptances are counted apart from bank 0's rings (src/dev/intc.mjs; docs/hle-gaps.md 4.6.1)",
  "S-CPU2": "(M10B) CPU 2 is not in the lab: when the GUI's post to CPU 2 (0x50aa9d4e) returns with exactly bank-2 bit 8 pending and one new ring [2][0] entry {0x60acb193, 0}, the stand-in acks the bit, drains the entry, does task 0x200e's command 3 (copy 28 bytes 0x62ee9408 -> 0xa33da484, (0xa33da778) -> 0xa33da49c) and posts CPU 2's reply as 0x50035afd(0, 0x60acbfb7, 0) would (ring [0][2], bank-0 bit 0x20); CPU 0 then takes IRQ 324 natively and the reply wakes the GUI. Anything else is an error, among it the swap path 0x50aaad0e taken when (0x62ee93e8) != 0. Task 0x200e is the audio sequencer (aud_seq strings, D) and the snapshot words are its level (peak) data (0x50aaab36..c8 keeps the maxima and increments 0x62ee93e8): lab RAM CPU 2 never wrote, so they read 0; on the camera the swap path is the usual one. Lifted with --cpu2 native: the post goes to CPU 2 (bank 2's IRQ 324), whose AUD_LEVEL_MONITOR answers it natively (docs/hle-gaps.md 4.6.1)",
};

const hex4 = (v) => '0x' + v.toString(16).padStart(4, '0');
// /api/controls: each row with uiin as an object and the EV names and GUI message names the
// image's tables give (tables: play.mjs Tables of the image).
export function controlsDoc(tables) {
  return CONTROL_ROWS.map((c) => {
    const r = { ...c };
    if (c.uiin) {
      const [group, byte, bit, code, type, polarity] = c.uiin;
      r.uiin = { group, byte, bit, code: hex4(code), type, polarity };
      r.ev = (type === 2 ? [0, 1] : [2]).map((k) => tables.ev_name((k << 16 | 0x02000000 | code) >>> 0));
    } else if (c.dial) r.ev = [tables.ev_name(c.dial[0])];
    else if (c.js_ev) r.ev = [c.js_ev, tables.ev.get(JS_EV_CENTRE) ?? null];
    else if (c.inject) r.ev = [tables.ev_name((0x02000000 | c.inject[0]) >>> 0), tables.ev_name((0x02010000 | c.inject[0]) >>> 0)];
    r.gui_names = c.gui.map((i) => tables.index_name(i));
    return r;
  });
}
// /api/screens.
export function screensDoc() {
  return { not_offered: NOT_OFFERED, stand_ins: STAND_INS };
}
